{
  "name": "Gate",
  "description": "Hold a gate open: a Request press opens it, a Close press closes it.",
  "version": "1.0.0",
  "variables": {
    "local": [],
    "inputs": [
      {
        "name": "Request",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "Start pushbutton, normally open: TRUE while pressed"
      },
      {
        "name": "Close",
        "type": "BOOL",
        "address": "%I0.1",
        "comment": "Stop pushbutton, normally open: TRUE while pressed. The rung breaks on a press."
      }
    ],
    "outputs": [
      {
        "name": "Open",
        "type": "BOOL",
        "address": "%Q0.0",
        "comment": "Open contactor command. It is also the memory that holds the motor on."
      }
    ]
  },
  "rungs": [
    {
      "id": "rung_1",
      "number": 1,
      "comment": "Start / stop with seal-in. The contact on Open under Request holds the coil on after Start is released; Close is in series before the branch, so Stop wins.",
      "branches": [
        {
          "id": "branch_1",
          "startCol": 1,
          "endCol": 4,
          "rows": [
            0,
            1
          ]
        }
      ],
      "gridConfig": {
        "cols": 8,
        "rows": 2,
        "cellWidth": 80,
        "cellHeight": 60
      },
      "grid": [
        [
          {
            "element": {
              "id": "stop",
              "type": "contact_nc",
              "variable": "Close",
              "row": 0,
              "col": 0
            },
            "hasWire": true
          },
          {
            "element": {
              "id": "start",
              "type": "contact_no",
              "variable": "Request",
              "row": 0,
              "col": 1
            },
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": {
              "id": "motor",
              "type": "coil",
              "variable": "Open",
              "row": 0,
              "col": 7
            },
            "hasWire": true
          }
        ],
        [
          {
            "element": null,
            "hasWire": false
          },
          {
            "element": {
              "id": "seal",
              "type": "contact_no",
              "variable": "Open",
              "row": 1,
              "col": 1
            },
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": false
