{
  "name": "Gate",
  "description": "Hold a gate open: (Request OR Open) AND NOT Close.",
  "version": "1.0.0",
  "variables": {
    "local": [],
    "inputs": [
      {
        "name": "Request",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "Request to open"
      },
      {
        "name": "Close",
        "type": "BOOL",
        "address": "%I0.1",
        "comment": "Close command"
      }
    ],
    "outputs": [
      {
        "name": "Open",
        "type": "BOOL",
        "address": "%Q0.0",
        "comment": "Gate open command"
      }
    ]
  },
  "blocks": [
    {
      "id": "var_request",
      "type": "variable",
      "variableName": "Request",
      "direction": "read",
      "position": {
        "x": 50,
        "y": 40
      },
      "outputs": [
        {
          "name": "OUT",
          "type": "BOOL"
        }
      ]
    },
    {
      "id": "var_open",
      "type": "variable",
      "variableName": "Open",
      "direction": "read",
      "position": {
        "x": 50,
        "y": 120
