    {
      "id": "var_close",
      "type": "variable",
      "variableName": "Close",
      "direction": "read",
      "position": {
        "x": 50,
        "y": 200
      },
      "outputs": [
        {
          "name": "OUT",
          "type": "BOOL"
        }
      ]
    },
    {
      "id": "or_hold",
      "type": "OR",
      "position": {
        "x": 260,
        "y": 70
      },
      "inputs": [
        {
          "name": "IN1",
          "type": "BOOL"
        },
        {
          "name": "IN2",
          "type": "BOOL"
