    {
      "id": "and_open",
      "type": "AND",
      "position": {
        "x": 460,
        "y": 120
      },
      "inputs": [
        {
          "name": "IN1",
          "type": "BOOL"
        },
        {
          "name": "IN2",
          "type": "BOOL"
        }
      ],
      "outputs": [
        {
          "name": "OUT",
          "type": "BOOL"
        }
      ]
    },
    {
      "id": "out_open",
      "type": "output",
      "variableName": "Open",
      "position": {
        "x": 660,
        "y": 120
      },
      "inputs": [
        {
          "name": "IN",
          "type": "BOOL"
        }
      ]
    }
  ],
  "connections": [
    {
      "id": "conn_var_request_or_hold_in1",
