{
  "name": "Gate",
  "description": "Two steps: IS_CLOSED and IS_OPEN.",
  "version": "1.0.0",
  "variables": {
    "local": [],
    "inputs": [
      {
        "name": "Request",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "Request to open"
      },
      {
        "name": "Close",
        "type": "BOOL",
        "address": "%I0.1",
        "comment": "Close command"
      }
    ],
    "outputs": [
      {
        "name": "Open",
        "type": "BOOL",
        "address": "%Q0.0",
        "comment": "Gate open command"
      }
    ]
  },
  "steps": [
    {
      "id": "step_closed",
      "name": "IS_CLOSED",
      "isInitial": true,
      "position": {
        "x": 200,
        "y": 50
      },
      "actions": [
        {
          "qualifier": "N",
          "actionName": "A_CLOSED",
          "comment": "Gate closed"
        }
      ]
    },
    {
      "id": "step_open",
      "name": "IS_OPEN",
      "isInitial": false,
      "position": {
        "x": 200,
        "y": 250
      },
      "actions": [
        {
          "qualifier": "N",
          "actionName": "A_OPEN",
          "comment": "Gate open"
        }
      ]
    }
  ],
  "transitions": [
    {
      "id": "t_open",
      "fromStep": "step_closed",
      "toStep": "step_open",
      "condition": "Request AND NOT Close",
      "comment": "",
      "position": {
        "x": 200,
        "y": 150
      }
    },
    {
      "id": "t_close",
      "fromStep": "step_open",
      "toStep": "step_closed",
      "condition": "Close",
      "comment": "",
      "position": {
        "x": 200,
        "y": 350
      }
    }
  ],
  "actions": [
    {
      "id": "A_CLOSED",
      "name": "A_CLOSED",
      "type": "ST",
      "body": "Open := FALSE;"
    },
    {
      "id": "A_OPEN",
      "name": "A_OPEN",
      "type": "ST",
      "body": "Open := TRUE;"
    }
  ],
  "metadata": {
    "author": "ZPLC Team",
    "created": "2026-10-19",
    "iecStandard": "IEC 61131-3",
    "notes": []
  }
}
